fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    // Compute current distance in a larger integer type to avoid overflow
    let diff = (a - b).abs() as i16;
    let moves = x as i16;
    
    // Compute the desired distance and clamp to the maximum possible (n - 1)
    let max_possible = (n - 1) as i16;
    let desired = diff + moves;
    let final_distance = if desired > max_possible {
        max_possible
    } else {
        desired
    };
    
    // Cast back to i8 for the return
    final_distance as i8
}

